/* Consultoria — Módulo 60: Casos práticos 10: lucro real, presumido, Simples Nacional e MEI diante da reforma (modo direto) */
window.MOD = window.MOD || {};
window.MOD.cons60 = (function(){
"use strict";
var CARDS = [["Qual a diferença entre regime de IRPJ e regime de IBS/CBS?", "IRPJ/CSLL: <b>real, presumido, arbitrado</b>. IBS/CBS: <b>regular, Simples (DAS) ou híbrido</b>. São eixos independentes."], ["Em 2026, quais as alíquotas de teste?", "<b>CBS 0,9%</b> e <b>IBS 0,1%</b> (ADCT, art. 125), compensáveis com PIS/Cofins."], ["Quando PIS/Cofins são extintos?", "A partir de <b>2027</b>, desde que instituída a CBS (ADCT, art. 126, II)."], ["IBS em 2027 e 2028?", "<b>0,05% estadual + 0,05% municipal</b>; CBS reduzida em 0,1 p.p. (ADCT, art. 127)."], ["Quem fica no regime regular em 2027?", "Quem <b>não optar</b> pelo Simples Nacional nem pelo MEI."], ["Qual a regra de crédito do Simples tradicional?", "O optante <b>não se credita</b>; o adquirente não optante tem crédito <b>equivalente ao cobrado</b> no regime único (CF, art. 146, § 3º)."], ["Como se apura o IBS/CBS no regime regular?", "<b>Débito (nas saídas) menos crédito (nas entradas)</b>; equivale à alíquota sobre o valor adicionado."], ["Vendas 1.000.000, compras 600.000, 26,5% hipotético: a recolher?", "<b>R$ 106.000</b> (IBS 70.800 + CBS 35.200)."], ["Limite de receita para optar pelo lucro presumido?", "<b>R$ 78.000.000</b> no ano anterior (ou R$ 6,5 mi x meses)."], ["IRPJ no presumido: alíquota e adicional?", "<b>15%</b> e adicional de <b>10%</b> sobre o que exceder R$ 20.000 por mês (R$ 60.000 por trimestre)."], ["Alíquota da CSLL para as demais pessoas jurídicas?", "<b>9%</b> (Perguntão PJ 2026, CSLL, Pergunta 003)."], ["O IBS/CBS por fora está na receita bruta do IRPJ/CSLL?", "Pelo texto da Receita, tributos não cumulativos destacados ficam fora; para o IBS/CBS, <b>confira</b> a norma vigente."], ["Qual a vantagem nova do presumido em 2027?", "<b>Crédito de IBS/CBS</b>, que o PIS/Cofins cumulativo não permitia."], ["Onde ficam IBS/CBS no Simples tradicional?", "<b>Dentro do DAS</b> (por dentro)."], ["E no Simples com regime regular?", "IBS/CBS <b>por fora</b>, com débitos e créditos mensais; IRPJ, CSLL, CPP e ISS/ICMS seguem no DAS."], ["Quando se pode optar pelo regime regular?", "Em <b>setembro</b> (efeitos 1º/01) e <b>março</b> (efeitos 1º/07)."], ["A opção é retratável?", "<b>Não</b>: é irretratável em cada semestre (LC 123, art. 13, § 10)."], ["Prazo de cancelamento da opção de 2026?", "Até <b>30/11/2026</b>, irretratável."], ["Prazos de indeferimento da opção pelo Simples?", "<b>30 dias</b> para regularizar e <b>20 dias úteis</b> para impugnar (termo da RFB)."], ["Faixas de receita de ME e EPP (texto da Receita sobre a LC 155/2016)?", "ME até <b>R$ 360.000</b>; EPP acima disso até <b>R$ 4.800.000</b>."], ["O cliente do lucro real prefere comprar do regime regular?", "Em regra, o <b>crédito integral</b> o favorece; o que conta é o <b>custo líquido</b> (nota - crédito)."], ["Exemplo: nota 100.000 de Simples (6%, partilha 15,6%).", "Crédito do cliente: <b>R$ 936</b>."], ["Exemplo: nota 101.200 de regime regular (26,5%).", "Crédito: <b>R$ 21.200</b>; custo líquido <b>R$ 80.000</b>."], ["Por que o Simples tradicional pode perder competitividade no B2B?", "Não credita as compras e transfere <b>pouco crédito</b> ao cliente: o tributo fica preso na cadeia."], ["Alíquota do crédito: onde consta?", "No <b>documento fiscal</b>; usa os percentuais de ICMS, IBS e CBS do Anexo para a faixa do mês (art. 23, § 2º)."], ["Compra no mês de início de atividade do fornecedor Simples?", "Usa a <b>menor alíquota</b> prevista nos Anexos (art. 23, § 3º)."], ["Quando se opta pelo SIMEI para 2027?", "Em <b>janeiro</b>, até <b>29/01/2027</b>."], ["O MEI é optante do Simples?", "<b>Sim</b>; a exclusão do Simples desenquadra o MEI."], ["Como se divide o IBS do MEI?", "<b>50% Município/DF</b> e <b>50% Estado/DF</b> do estabelecimento (LC 123, art. 22)."], ["O MEI credita nas compras?", "<b>Não</b> apropria crédito no regime único (EC 132, art. 146, § 3º, I; confira o alcance para o MEI)."], ["Compras feitas por MEI, para a repartição do IBS?", "Consideradas <b>consumo final</b> (LC 227/2026, art. 106, § 5º)."], ["O que NÃO está nas fontes e deve ser conferido?", "<b>Limite de receita do MEI</b>, valor do DAS-MEI e o <b>crédito do adquirente</b> nas compras de MEI."], ["Mesmo faturamento: quem entrega mais crédito ao cliente?", "<b>Real, presumido e híbrido</b> (crédito integral). O Simples tradicional entrega só o IBS/CBS cobrado no DAS."], ["Real x presumido: quando o presumido costuma ganhar?", "Quando a <b>margem real é alta</b> frente ao percentual presumido (8%/12%)."], ["Exemplo do quadro: IRPJ+CSLL do real e do presumido?", "Real <b>24.600</b>; presumido <b>6.840</b> (trimestre, hipotético)."], ["Como se lança a compra tributada no regime regular?", "D Estoque (sem o tributo); D IBS/CBS a recuperar; C Fornecedores."], ["O Simples (ME/EPP) entrega ECF?", "<b>Não</b>: PGDAS-D e DASN."], ["Quais os dois limites a verificar na consultoria?", "<b>EPP: R$ 4,8 mi</b> e <b>presumido: R$ 78 mi</b> (receita do ano anterior); MEI: <b>confira</b>."], ["Por que simular antes de setembro e março?", "A opção pelo regime regular é <b>semestral e irretratável</b>."]];
var QS = [["Em 2026, o valor de CBS (0,9%) e IBS (0,1%) recolhido é compensado com PIS/Cofins devidos e, faltando débitos, pode ser compensado com outro tributo federal ou ressarcido em até 60 dias (ADCT, art. 125, §§ 1º e 2º).", "C", "Inédita", "É a literalidade dos §§ 1º e 2º do art. 125 do ADCT."], ["Em 2026, os optantes pelo Simples Nacional recolhem IBS e CBS às alíquotas de teste dentro do DAS.", "E", "Inédita", "As alíquotas de IBS/CBS não se aplicam às operações dos optantes do Simples em 2026."], ["A partir de 2027, a empresa que não optar pelo Simples nem pelo MEI passa ao lucro presumido.", "E", "Inédita", "Lucro presumido é regime de IRPJ/CSLL. Quem não opta fica no regime regular de IBS/CBS."], ["Optar pelo lucro presumido não impede, em regra, o direito a crédito de IBS/CBS no regime regular.", "C", "Inédita", "O presumido só altera a base do IRPJ/CSLL; o regime de IBS/CBS é outro."], ["No lucro real e no presumido, o IBS e a CBS no regime regular são apurados por débito menos crédito, ou seja, de forma não cumulativa.", "C", "Inédita", "Ambos são contribuintes do regime regular; o regime de IRPJ não muda a técnica."], ["No lucro presumido, o PIS/Cofins cumulativo (3,65%) continua após 2027, pois a base do IRPJ é presumida.", "E", "Inédita", "PIS/Pasep e Cofins são extintos a partir de 2027 (ADCT, art. 126, II). O presumido passa a ter crédito de IBS/CBS."], ["No lucro presumido, a apropriação de crédito de IBS/CBS reduz a base do IRPJ, porque o lucro é calculado sobre custos e despesas.", "E", "Inédita", "A base é um percentual da receita bruta, independentemente de custos, créditos ou perdas."], ["Está obrigada ao lucro real a pessoa jurídica cuja receita total no ano-calendário anterior excedeu R$ 78.000.000 (ou R$ 6.500.000 multiplicado pelo número de meses, se inferior a 12).", "C", "Inédita", "É a alínea 'a' da Pergunta 006 do Cap. XIII do Perguntão PJ 2026."], ["A opção pelo regime regular de IBS/CBS pelo optante do Simples pode ser feita em qualquer mês do ano.", "E", "Inédita", "Somente em setembro e março (LC 123, art. 13, § 10; Manual do CGSN)."], ["Quem optou pelo regime regular em setembro/2026 e não renunciar em março ou setembro seguintes mantém o regime nos semestres posteriores.", "C", "Inédita", "A ausência de renúncia implica manutenção do regime regular (Roteiro do CGSN, item 4.2)."], ["O optante do Simples que recebeu ressarcimento de créditos de IBS/CBS no ano corrente ou no anterior não pode se retirar do regime regular.", "C", "Inédita", "Vedação descrita no Perguntão PJ 2026 sobre a LC 124/2025."], ["No Simples tradicional, o adquirente não optante tem crédito de IBS/CBS igual ao que teria se o fornecedor fosse do regime regular.", "E", "Inédita", "O crédito equivale apenas ao IBS/CBS cobrado no regime único (LC 123, art. 23, § 1º-A)."], ["O adquirente não optante do Simples tem direito a crédito de IBS e CBS nas compras de ME/EPP optante em montante equivalente ao cobrado por meio do regime único (LC 123, art. 23, § 1º-A).", "C", "Inédita", "É a redação do § 1º-A, em linha com a EC 132 (art. 146, § 3º, II)."], ["O crédito do adquirente na compra de fornecedor do Simples tradicional equivale ao IBS/CBS que ele teria se o fornecedor fosse do regime regular.", "E", "Inédita", "O crédito é limitado ao que o regime único cobra, normalmente bem menor."], ["A alíquota usada no cálculo do crédito deve ser informada no documento fiscal e corresponde aos percentuais de ICMS, IBS e CBS previstos nos Anexos para a faixa do mês da operação.", "C", "Inédita", "Art. 23, § 2º, da LC 123."], ["O comprador do lucro real deve escolher o fornecedor pelo menor valor da nota, sem considerar o crédito.", "E", "Inédita", "O custo relevante é o líquido do crédito: nota menos crédito apropriável."], ["Todo MEI é optante pelo Simples Nacional, e a exclusão do Simples implica o desenquadramento automático do MEI.", "C", "Inédita", "Roteiro do CGSN, apresentação do documento."], ["Para retornar à condição de MEI basta regularizar as pendências que levaram à exclusão.", "E", "Inédita", "É necessário atender também aos requisitos para ingresso no Simples."], ["Do IBS recolhido pelo MEI, 50% vai ao Município (ou DF) e 50% ao Estado (ou DF) do estabelecimento.", "C", "Inédita", "LC 123, art. 22, V e VI (redação da LC 227/2026)."], ["A opção pelo SIMEI passou a ser feita em setembro, junto com a do Simples.", "E", "Inédita", "Não houve alteração: a opção pelo SIMEI é em janeiro (até 29/01/2027)."], ["O Simples Nacional é sempre mais vantajoso que o lucro presumido, porque o DAS tem alíquota menor.", "E", "Inédita", "Depende da margem, dos insumos, do perfil do cliente e do crédito; só a simulação responde."], ["As pessoas jurídicas optantes pelo Simples Nacional (ME/EPP) estão desobrigadas da ECF, por apresentarem a DASN.", "C", "Inédita", "Perguntão PJ 2026, ECF, Pergunta 002, item I."], ["Empresa excluída do Simples com efeitos dentro do ano-calendário entrega a DASN do período no Simples e a ECF do restante do ano.", "C", "Inédita", "Atenção da Pergunta 002 do Perguntão PJ 2026."], ["Tributos recuperáveis de IBS/CBS nas compras integram o custo do estoque do contribuinte do regime regular.", "E", "Inédita", "Em regra são ativo a recuperar e não compõem o custo (CPC 16: confira)."]];
var EX = {"S1": {"t": "mc", "instr": "2026, lucro presumido, receita mensal de R$ 500.000. PIS/Cofins cumulativo (3,65%). Teste de CBS 0,9% + IBS 0,1% totalmente compensável. Quanto sobra a pagar de PIS/Cofins?", "options": ["R$ 13.250", "R$ 18.250", "R$ 5.000", "R$ 23.250"], "answer": 0, "why": "PIS/Cofins = 500.000 x 3,65% = 18.250. Teste = 500.000 x 1% = 5.000. Sobra 18.250 - 5.000 = R$ 13.250."}, "S2": {"t": "sort", "instr": "Destino do tributo na transição", "buckets": ["Extinto a partir de 2027", "Reduzido de 2029 a 2032 e extinto em 2033", "Continua (tributo sobre a renda)"], "items": [["PIS/Pasep", 0], ["Cofins", 0], ["ICMS", 1], ["ISS", 1], ["IRPJ", 2], ["CSLL", 2]], "why": "PIS/Cofins somem em 2027 (ADCT, art. 126, II); ICMS e ISS caem de 2029 a 2032 e acabam em 2033; IRPJ e CSLL não são alterados pela EC 132."}, "S3": {"t": "gap", "instr": "A partir de 2027, o contribuinte que não optar pelo Simples Nacional nem pelo MEI fica sujeito ao regime", "before": "", "after": " de IBS e CBS.", "options": ["regular", "especial", "de teste", "único"], "answer": 0, "why": "Regra da LC 124/2025 descrita no Perguntão PJ 2026: sem opção pelo Simples/MEI, aplica-se o regime regular."}, "S4": {"t": "order", "instr": "Ordene a linha do tempo da transição:", "items": ["2026: teste de CBS 0,9% e IBS 0,1%", "2027: PIS/Cofins extintos e CBS cobrada", "2029 a 2032: redução gradual de ICMS e ISS", "2033: ICMS e ISS extintos"], "why": "Teste em 2026; extinção de PIS/Cofins em 2027; escalonamento do ICMS/ISS de 2029 a 2032; extinção em 2033."}, "S5": {"t": "mc", "instr": "Regime regular, alíquota-exemplo hipotética de 26,5%. Vendas de R$ 800.000 e compras tributadas de R$ 500.000 (valores sem o tributo). Quanto de IBS/CBS a recolher?", "options": ["R$ 79.500", "R$ 212.000", "R$ 132.500", "R$ 344.500"], "answer": 0, "why": "Débito: 26,5% x 800.000 = 212.000. Crédito: 26,5% x 500.000 = 132.500. A recolher: R$ 79.500 (= 26,5% x 300.000)."}, "S6": {"t": "mc", "instr": "Lucro presumido, comércio (8% IRPJ / 12% CSLL), receita trimestral de R$ 500.000. Quanto de IRPJ + CSLL (receita sem IBS/CBS)?", "options": ["R$ 11.400", "R$ 5.400", "R$ 6.000", "R$ 18.000"], "answer": 0, "why": "Base IRPJ: 8% x 500.000 = 40.000; 15% = 6.000 (sem adicional, pois 40.000 < 60.000). Base CSLL: 12% x 500.000 = 60.000; 9% = 5.400. Total R$ 11.400."}, "S7": {"t": "mc", "instr": "Vendas de R$ 200.000 e compras tributadas de R$ 400.000 no mês (26,5% hipotético). Qual o resultado da apuração?", "options": ["Saldo credor de R$ 53.000", "A recolher R$ 53.000", "Saldo credor de R$ 106.000", "Zero"], "answer": 0, "why": "Débito 53.000; crédito 106.000. Saldo credor de R$ 53.000 (o uso segue a lei: confira)."}, "S8": {"t": "multi", "instr": "Sobre o lucro presumido, marque as corretas:", "options": ["Pode optar quem teve receita total de até R$ 78.000.000 no ano anterior (e não é obrigado ao real)", "A base do IRPJ é um percentual da receita bruta (por exemplo 8% e 32%)", "Por ser presumido, não apropria crédito de IBS/CBS no regime regular", "Bancos comerciais podem optar pelo presumido", "Quem tem lucros ou rendimentos do exterior fica obrigado ao lucro real"], "answers": [0, 1, 4], "why": "Bancos comerciais e quem tem lucros do exterior são obrigados ao real (Perguntão PJ 2026, Cap. XIII, Pergunta 006). O regime de IRPJ não impede o crédito de IBS/CBS."}, "S9": {"t": "mc", "instr": "DAS de R$ 6.000 sobre receita de R$ 100.000 (hipotético). A partilha de IBS + CBS é de 15,60%. Qual o IBS/CBS contido no DAS e o crédito do adquirente?", "options": ["R$ 936", "R$ 26.500", "R$ 6.000", "R$ 5.064"], "answer": 0, "why": "6.000 x 15,60% = 936 (CBS 925,80 + IBS 10,20). O crédito do cliente equivale ao cobrado no DAS."}, "S10": {"t": "mc", "instr": "Uma empresa do Simples opta pelo regime regular de IBS/CBS em março de 2027. A partir de quando produz efeitos?", "options": ["1º/07/2027", "1º/04/2027", "1º/01/2028", "Imediatamente"], "answer": 0, "why": "Opção em março: efeitos a partir de 1º de julho do mesmo ano (Roteiro do CGSN, item 4.1)."}, "S11": {"t": "sort", "instr": "No Simples com regime regular de IBS/CBS, onde fica cada tributo?", "buckets": ["Dentro do DAS", "Fora do DAS (apuração regular)"], "items": [["IRPJ", 0], ["CSLL", 0], ["CPP", 0], ["ISS", 0], ["IBS", 1], ["CBS", 1]], "why": "O regime regular retira do DAS as parcelas de IBS e CBS; os demais seguem no DAS."}, "S12": {"t": "gap", "instr": "Complete o prazo de opção pelo Simples Nacional para 2027:", "before": "Entre 1º e ", "after": " de setembro de 2026, com efeitos em 1º/01/2027.", "options": ["30", "15", "10", "20"], "answer": 0, "why": "Prazo de 1º a 30/09/2026 (Roteiro do CGSN)."}, "S13": {"t": "order", "instr": "Ordene o caminho de uma empresa que ainda não é optante e quer o Simples híbrido em 2027:", "items": ["Optar pelo Simples (1º a 30/09/2026)", "Formalizar a opção pelo regime regular de IBS/CBS (até 30/09/2026)", "Efeitos de ambas a partir de 01/01/2027", "Renunciar ou manter o regime regular em março/2027, com efeitos em 1º/07/2027"], "why": "Primeiro o Simples, depois o regime regular; os efeitos são de 1º/01/2027; as revisões ocorrem em março e setembro."}, "S14": {"t": "mc", "instr": "Cliente do lucro real compra R$ 100.000 de fornecedor do Simples tradicional (DAS efetivo de 6%, partilha de IBS+CBS de 15,6%, hipotéticos). Qual o crédito de IBS/CBS?", "options": ["R$ 936", "R$ 26.500", "R$ 6.000", "R$ 15.600"], "answer": 0, "why": "O crédito equivale ao IBS/CBS cobrado no DAS: 100.000 x 6% x 15,6% = 936."}, "S15": {"t": "mc", "instr": "Fornecedor do regime regular vende por R$ 80.000 mais IBS/CBS de 26,5% (hipotético) a cliente do lucro real. Qual o custo líquido do cliente?", "options": ["R$ 80.000", "R$ 101.200", "R$ 21.200", "R$ 59.924"], "answer": 0, "why": "Paga 101.200 e credita 21.200: custo líquido R$ 80.000."}, "S16": {"t": "multi", "instr": "Quando o regime regular (híbrido) tende a favorecer o fornecedor do Simples?", "options": ["Vende a clientes do lucro real que aproveitam crédito", "Tem muitos insumos tributados", "Vende quase só ao consumidor final", "O cliente exige crédito integral em contrato", "Quer poder sair do regime a qualquer mês"], "answers": [0, 1, 3], "why": "O regime regular devolve crédito integral ao cliente e permite creditar as compras. A saída só ocorre em março/setembro, sem retratação no semestre."}, "S17": {"t": "sort", "instr": "Perfil do fornecedor do Simples: o que tende a servir melhor?", "buckets": ["Tradicional", "Regime regular (híbrido)"], "items": [["Serviço com poucos insumos, venda a pessoa física", 0], ["Comércio varejista para consumidor final", 0], ["Indústria com muitos insumos vendendo a empresas do lucro real", 1], ["Fornecedor de grande empresa que exige crédito pleno", 1], ["Atacado para clientes do regime regular", 1]], "why": "Quem vende ao consumidor final não transfere crédito útil; quem vende a contribuinte regular ganha competitividade com o crédito integral."}, "S18": {"t": "mc", "instr": "Até quando se faz a opção pelo SIMEI para 2027?", "options": ["29/01/2027, último dia útil de janeiro", "30/09/2026", "31/03/2027", "30/11/2026"], "answer": 0, "why": "A opção pelo SIMEI continua em janeiro; em 2027, até 29/01 (Roteiro do CGSN)."}, "S19": {"t": "mc", "instr": "O IBS recolhido pelo MEI no mês foi de R$ 10,00 (valor hipotético). Quanto vai ao Município do estabelecimento?", "options": ["R$ 5,00", "R$ 10,00", "R$ 2,50", "Nada"], "answer": 0, "why": "50% do IBS do MEI vai ao Município (ou DF) e 50% ao Estado (ou DF): LC 123, art. 22, V e VI."}, "S20": {"t": "mc", "instr": "Cliente do lucro real compra R$ 8.000 de ME do Simples tradicional (partilha de IBS/CBS = 0,936% do preço, hipotética). Qual o crédito?", "options": ["R$ 74,88", "R$ 2.120", "R$ 8.000", "R$ 936"], "answer": 0, "why": "8.000 x 0,936% = R$ 74,88."}, "S21": {"t": "multi", "instr": "Sobre o MEI, segundo os manuais do CGSN, marque as corretas:", "options": ["Todo MEI é optante do Simples Nacional", "A exclusão do Simples gera desenquadramento automático do MEI", "Para voltar a ser MEI basta regularizar as pendências", "A opção pelo SIMEI é feita em janeiro"], "answers": [0, 1, 3], "why": "Regularizar pendências não basta: é preciso cumprir os requisitos de ingresso no Simples."}, "S22": {"t": "mc", "instr": "Simples com regime regular: DAS efetivo de 6% (hipotético) sobre vendas de R$ 300.000, retirando-se a parcela de IBS/CBS de 0,936% do preço. Qual o DAS remanescente?", "options": ["R$ 15.192", "R$ 18.000", "R$ 2.808", "R$ 39.750"], "answer": 0, "why": "DAS sem IBS/CBS: 6% - 0,936% = 5,064% x 300.000 = R$ 15.192."}, "S23": {"t": "mc", "instr": "Lucro presumido (comércio), receita trimestral de R$ 300.000. Qual o IRPJ + CSLL (8% / 12%; 15% e 9%; sem adicional)?", "options": ["R$ 6.840", "R$ 24.600", "R$ 3.600", "R$ 3.240"], "answer": 0, "why": "IRPJ: 8% x 300.000 = 24.000 x 15% = 3.600. CSLL: 12% x 300.000 = 36.000 x 9% = 3.240. Total R$ 6.840."}, "S24": {"t": "mc", "instr": "Regime regular. Compra de R$ 50.000 com IBS/CBS de R$ 13.250. Qual o valor debitado em Estoque?", "options": ["R$ 50.000", "R$ 63.250", "R$ 13.250", "R$ 36.750"], "answer": 0, "why": "O tributo recuperável vai a 'IBS/CBS a recuperar' e não compõe o custo do estoque (CPC 16: confira)."}, "S25": {"t": "multi", "instr": "Sobre as obrigações acessórias, marque as corretas:", "options": ["ME/EPP do Simples entregam PGDAS-D", "O optante do Simples está desobrigado da ECF", "Quem lucra pelo presumido está dispensado de qualquer registro de inventário", "Empresa excluída do Simples no ano entrega DASN do período e ECF do restante", "Pessoa jurídica do lucro real apresenta ECF"], "answers": [0, 1, 3, 4], "why": "O presumido deve manter Registro de Inventário. As demais afirmativas constam do Perguntão PJ 2026 (ECF, Perguntas 001 e 002)."}, "S26": {"t": "match", "instr": "Ligue o porte/regime ao ponto-chave da consultoria", "pairs": [["MEI", "Limite de receita, desenquadramento e crédito ao cliente"], ["Simples (ME/EPP)", "Tradicional x híbrido, em setembro e março"], ["Lucro presumido", "Comparar com o real e o limite de R$ 78 milhões"], ["Lucro real", "Controle de créditos, estornos e saldo credor"]], "why": "Cada regime tem um ponto de atenção principal."}, "S27": {"t": "order", "instr": "Ordene as etapas de uma consultoria de escolha de regime:", "items": ["Diagnosticar receita, atividade e regime atual", "Mapear compras, créditos e perfil dos clientes", "Simular a carga em cada regime", "Decidir e optar dentro do prazo", "Ajustar contabilidade, notas e obrigações acessórias"], "why": "Primeiro o diagnóstico, depois a simulação, a decisão no prazo e a implantação."}};
for(var i=0;i<QS.length;i++) EX["T"+i]={t:"ce", qi:i};
var TEORIA = {"V1": [{"h": "Duas camadas que não se confundem", "b": "<div class=\"box\"><span class=\"bl\">Ideia central</span><p><b>Lucro real, lucro presumido e arbitrado</b> definem como se apuram <b>IRPJ e CSLL</b>. Já o <b>regime de IBS/CBS</b> é outro eixo: <b>regular</b> (débito menos crédito), <b>Simples Nacional</b> (IBS/CBS no DAS) ou <b>Simples com opção pelo regime regular</b> (híbrido). A partir de 2027, quem <b>não optar pelo Simples nem pelo MEI</b> fica no <b>regime regular</b> de IBS/CBS (texto da Receita sobre a LC 124/2025, no Perguntão PJ 2026).</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Regime</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IBS/CBS</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Crédito nas próprias compras</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Crédito entregue ao cliente</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Lucro real</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Regular: débito - crédito</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Sim</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Integral (o destacado na nota)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Lucro presumido</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Regular: débito - crédito</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Sim (o presumido só muda a base do IRPJ/CSLL)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Integral</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Simples Nacional tradicional</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Dentro do DAS</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>Não</b> (CF, art. 146, § 3º, I, na redação da EC 132)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Equivalente ao IBS/CBS cobrado no DAS (art. 146, § 3º, II da CF; LC 123, art. 23, § 1º-A)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Simples com regime regular (híbrido)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IBS/CBS por fora do DAS; o resto continua no DAS</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Sim</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Integral</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>MEI</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>DAS-MEI (valor fixo)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Não apropria crédito</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Confira no regulamento (ver unidade 5)</td></tr></table></div><div class=\"box trap\"><span class=\"bl\">Pegadinha</span><p>Escolher <b>lucro presumido</b> não tira o direito a crédito de IBS/CBS: o presumido é regime de <b>IRPJ/CSLL</b>. Só o optante do Simples <b>tradicional</b> não se credita.</p></div>"}, {"h": "Linha do tempo (o que o texto confirma)", "b": "<div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Quando</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>O que acontece</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Base</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2026</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Teste: <b>CBS 0,9%</b> e <b>IBS 0,1%</b>, compensados com PIS/Cofins; sem débitos suficientes, compensa com outro tributo federal ou ressarce em até 60 dias. Quem cumprir as acessórias pode ser dispensado do recolhimento, nos termos de lei complementar</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ADCT, art. 125 (EC 132)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2026 (Simples)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>As alíquotas de IBS/CBS <b>não se aplicam</b> às operações dos optantes do Simples</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Texto da Receita sobre a LC 124/2025</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2027</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>PIS/Pasep e Cofins extintos</b> (desde que instituída a CBS); IPI com alíquota zero, exceto Zona Franca de Manaus</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ADCT, art. 126</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2027 e 2028</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IBS a <b>0,05% estadual + 0,05% municipal</b>; CBS reduzida em 0,1 ponto percentual</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ADCT, art. 127</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2029 a 2032</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ICMS e ISS em 9/10, 8/10, 7/10 e 6/10</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ADCT, art. 128</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2033</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ICMS e ISS <b>extintos</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ADCT, art. 129</td></tr></table></div>"}, {"h": "Caso 2026: presumido x real com a compensação do teste", "b": "<div class=\"box\"><span class=\"bl\">Hipótese</span><p>Mês de 2026. Receita de <b>R$ 1.000.000</b>. Teste: CBS 0,9% = R$ 9.000 + IBS 0,1% = R$ 1.000 = <b>R$ 10.000</b> a compensar com PIS/Cofins (compensação integral; confira o regulamento).</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Passo</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Lucro presumido (PIS/Cofins cumulativo)</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Lucro real (PIS/Cofins não cumulativo)</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Alíquota do PIS/Cofins</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>0,65% + 3% = 3,65%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>1,65% + 7,6% = 9,25%</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Débito de PIS/Cofins</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>1.000.000 x 3,65% = <b>36.500</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>1.000.000 x 9,25% = <b>92.500</b></td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Crédito de PIS/Cofins</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Não há (regime cumulativo)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Compras de 600.000 x 9,25% = <b>55.500</b> (hipótese: tudo gera crédito)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>PIS/Cofins antes da compensação</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>36.500</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>92.500 - 55.500 = 37.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Compensação com o teste (10.000)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>-10.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>-10.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>PIS/Cofins a pagar</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>26.500</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>27.000</b></td></tr></table></div><div class=\"box tip\"><span class=\"bl\">Dica</span><p>As alíquotas de 0,65%, 3%, 1,65% e 7,6% e o limite de R$ 78 milhões estão no Perguntão PJ 2026. O percentual de compensação e a dispensa de recolhimento dependem da lei e do regulamento: confira.</p></div>"}], "V2": [{"h": "Apuração do IBS/CBS: débito - crédito", "b": "<div class=\"box\"><span class=\"bl\">Hipótese</span><p>Alíquota-exemplo <b>hipotética</b> de plena vigência: IBS 17,7% + CBS 8,8% = <b>26,5%</b> (só para o exercício; a alíquota real depende de resolução do Senado e de lei). Valores sempre sem o IBS/CBS, que é cobrado por fora.</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Linha</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IBS (17,7%)</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>CBS (8,8%)</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Total (26,5%)</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Vendas do mês: R$ 1.000.000 (débito)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>177.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>88.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>265.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Compras tributadas: R$ 600.000 (crédito)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>106.200</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>52.800</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>159.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>A recolher (débito - crédito)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>70.800</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>35.200</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>106.000</b></td></tr></table></div><div class=\"box tip\"><span class=\"bl\">Conferência</span><p>O resultado é a alíquota sobre o <b>valor adicionado</b>: 26,5% x (1.000.000 - 600.000) = <b>R$ 106.000</b>.</p></div><div class=\"box\"><span class=\"bl\">Saldo credor</span><p>Vendas de R$ 200.000 (débito 53.000) e compras de R$ 400.000 (crédito 106.000): saldo credor de <b>R$ 53.000</b>, que não é pago. O uso do saldo (compensação, ressarcimento) segue a LC 214/2025 e o regulamento: <b>confira</b>. O ressarcimento recebido também importa para o optante do Simples que queira sair do regime regular (unidade 3).</p></div><div class=\"box tip\"><span class=\"bl\">Fim do PIS/Cofins</span><p>O lucro <b>real</b> deixa a não cumulatividade de PIS/Cofins (9,25%) e o <b>presumido</b> deixa o regime cumulativo (3,65%) em 2027. O presumido <b>passa a ter crédito</b> de IBS/CBS, o que antes não tinha em PIS/Cofins.</p></div>"}, {"h": "Reflexos no IRPJ e na CSLL", "b": "<div class=\"box\"><span class=\"bl\">Lucro presumido</span><p>Pode optar quem teve receita total no ano anterior de até <b>R$ 78.000.000</b> (ou R$ 6.500.000 x meses, se o período for menor que 12) e não esteja obrigado ao real. Base: <b>percentual da receita bruta</b> (8% e 32% no IRPJ; 12% e 32% na CSLL). IRPJ de <b>15%</b> mais adicional de <b>10%</b> sobre o que exceder <b>R$ 20.000 por mês</b> (R$ 60.000 no trimestre); CSLL de <b>9%</b> (Perguntão PJ 2026).</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Trimestre, receita R$ 1.000.000</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Comércio (8% / 12%)</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Serviços em geral (32% / 32%)</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Base do IRPJ</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>80.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>320.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IRPJ 15%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>12.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>48.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Adicional 10% sobre o excedente de 60.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>26.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Base da CSLL</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>120.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>320.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>CSLL 9%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>10.800</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>28.800</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>IRPJ + CSLL</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>24.800</b> (2,48%)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>102.800</b> (10,28%)</td></tr></table></div><div class=\"box trap\"><span class=\"bl\">O que o texto da Receita diz sobre a receita</span><p>Na receita bruta <b>incluem-se os tributos sobre ela incidentes</b> (o ICMS integra e é parcela redutora na receita líquida) e <b>não se incluem os tributos não cumulativos cobrados destacadamente</b> do comprador, de que o vendedor é mero depositário (como o IPI). Como o IBS/CBS por fora entra nessa lógica para o IRPJ/CSLL, e se há norma própria, <b>confira na lei e no regulamento</b>. Os exemplos acima usam receita sem IBS/CBS.</p></div><div class=\"box tip\"><span class=\"bl\">Lucro real</span><p>A base é o <b>lucro contábil ajustado</b> (Lalur dentro da ECF). Os tributos de IBS/CBS <b>recuperáveis</b> não são custo: o crédito vai a 'tributos a recuperar'. Por isso, a boa gestão dos créditos melhora o lucro.</p></div>"}], "V3": [{"h": "Simples tradicional: IBS e CBS dentro do DAS", "b": "<div class=\"box\"><span class=\"bl\">Regra</span><p>Por padrão, o optante do Simples tem IBS e CBS <b>apurados por dentro</b> e recolhidos no <b>DAS</b> (Manual do CGSN). Ele <b>não se credita</b> nas compras; o adquirente não optante tem crédito <b>equivalente ao IBS/CBS cobrado</b> no DAS (LC 123, art. 23, § 1º-A, na redação da LC 227/2026). A alíquota do crédito vai na nota e corresponde aos percentuais de ICMS, IBS e CBS do Anexo para a faixa do mês (§ 2º).</p></div><div class=\"box\"><span class=\"bl\">Hipótese</span><p>Alíquota efetiva do DAS de <b>6%</b> sobre a receita de R$ 100.000 (<b>hipotética</b>; a real vem do Anexo e da receita dos 12 meses). Partilha do Anexo III em 2027-2028, 1ª faixa (LC 227/2026): IRPJ 4,00%, CSLL 3,50%, CBS 15,43%, CPP 43,40%, ISS 33,50%, IBS 0,17%.</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Tributo no DAS</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Percentual da partilha</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>R$ sobre o DAS de 6.000</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IRPJ</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>4,00%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>240,00</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>CSLL</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>3,50%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>210,00</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>CBS</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>15,43%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>925,80</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>CPP</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>43,40%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2.604,00</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ISS</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>33,50%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2.010,00</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IBS</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>0,17%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>10,20</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>Total do DAS</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>100%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>6.000,00</b></td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>Crédito do adquirente (CBS + IBS)</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>15,60%</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>936,00</b> (0,936% do preço)</td></tr></table></div><div class=\"box trap\"><span class=\"bl\">Pegadinha</span><p>O crédito do cliente <b>não é 26,5%</b>: é só a parte de IBS/CBS que o DAS efetivamente cobra (aqui R$ 936 sobre R$ 100.000). Em 2029 a partilha da 1ª faixa passa a CBS 15,60% e IBS 3,35% (confira o Anexo vigente).</p></div>"}, {"h": "Regime regular de IBS/CBS por opção (híbrido)", "b": "<div class=\"box\"><span class=\"bl\">Como funciona</span><p>O optante pode apurar IBS e CBS pelo <b>regime regular</b>; então essas parcelas <b>não são cobradas no DAS</b> (LC 123, art. 13, §§ 9º a 11, redação da LC 214/2025, com alterações da LC 227/2026). <b>Fora do DAS:</b> IBS e CBS, com débitos e créditos mês a mês. <b>Dentro do DAS:</b> IRPJ, CSLL, CPP, ICMS/ISS e demais tributos unificados.</p></div><div class=\"box\"><span class=\"bl\">Mesma operação, mesmo mês</span><p>Receita de R$ 100.000 (ex-tributo), compras de R$ 50.000, 26,5% hipotético. <b>Tradicional:</b> DAS de 6.000; crédito do cliente 936; sem crédito nas compras. <b>Híbrido:</b> DAS sem a parcela de IBS/CBS = 6.000 - 936 = <b>5.064</b>; IBS/CBS: débito 26.500 - crédito 13.250 = <b>13.250</b>; crédito do cliente <b>26.500</b>.</p></div><div class=\"box trap\"><span class=\"bl\">Atenção</span><p>Os 26,5% são a alíquota-exemplo de <b>plena vigência</b>. Em 2027-2028 o IBS é 0,1% e a CBS é a de referência menos 0,1 p.p. (ADCT, art. 127): simule sempre com as alíquotas do ano.</p></div>"}, {"h": "Prazos (Manuais do CGSN, versão de 18/09/2026)", "b": "<div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Evento</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Regra</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Opção pelo Simples para 2027</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>De <b>1º a 30/09/2026</b> (Portal do Simples ou e-CAC), com efeitos a partir de <b>01/01/2027</b>; não há mais opção em janeiro</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Opção pelo regime regular de IBS/CBS</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Apenas em <b>setembro e março</b>. Setembro: efeitos em <b>1º de janeiro</b> seguinte. Março: efeitos em <b>1º de julho</b> do mesmo ano</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Natureza</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>Irretratável</b> em cada semestre (LC 123, art. 13, § 10)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Renúncia</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Também em março e setembro; <b>sem renúncia, o regime regular se mantém</b> nos semestres seguintes</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Cancelamento da opção de 2026</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Até <b>30/11/2026</b>, em caráter irretratável (início previsto em 02/11/2026)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Quem não era optante</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Opta antes pelo Simples (até 30/09/2026) e depois formaliza o regime regular; pode pedir o regime regular mesmo com opção indeferida, se tiver convicção de que entrará (condicionado ao deferimento)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Início de atividade</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Opção pelo Simples feita no MAT, no momento da inscrição do CNPJ; efeitos desde a inscrição</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Indeferimento</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>30 dias</b> corridos para regularizar; impugnação à RFB em <b>20 dias úteis</b></td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Saída do regime regular</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Vedada a quem recebeu <b>ressarcimento de créditos</b> de IBS/CBS no ano corrente ou no anterior</td></tr></table></div><div class=\"box tip\"><span class=\"bl\">Hoje (03/10/2026)</span><p>A janela de setembro/2026 já fechou. Quem não optou pelo regime regular recolhe IBS/CBS no DAS no 1º semestre de 2027 e pode optar em <b>março/2027</b>, com efeitos em <b>1º/07/2027</b>.</p></div>"}], "V4": [{"h": "O cliente compara custo líquido de crédito, não o valor da nota", "b": "<div class=\"box\"><span class=\"bl\">Hipótese</span><p>Alíquota-exemplo <b>hipotética</b> de plena vigência: IBS 17,7% + CBS 8,8% = <b>26,5%</b> (só para o exercício; a alíquota real depende de resolução do Senado e de lei). Valores sempre sem o IBS/CBS, que é cobrado por fora. Alíquota efetiva do DAS: 6%, com 15,6% de IBS/CBS na partilha (hipotética).</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Fornecedor R (regime regular)</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Fornecedor S (Simples tradicional)</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Insumos: 50.000 + 26,5% = 63.250 (credita 13.250)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Insumos: 50.000 + 26,5% = 63.250 (<b>sem crédito</b>: custo)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Preço sem tributo: 80.000; IBS/CBS 21.200; <b>nota 101.200</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>Nota 100.000</b> (tudo por dentro); DAS 6% = 6.000</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Apura: 21.200 - 13.250 = 7.950. Margem: 101.200 - 63.250 - 7.950 = <b>30.000</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Margem: 100.000 - 63.250 - 6.000 = <b>30.750</b></td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Cliente (lucro real) credita <b>21.200</b>: custo líquido <b>80.000</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Cliente credita 100.000 x 0,936% = <b>936</b>: custo líquido <b>99.064</b></td></tr></table></div><div class=\"box trap\"><span class=\"bl\">Conclusão</span><p>A nota de S parece 1.200 mais barata, mas, <b>líquida do crédito</b>, custa <b>R$ 19.064 a mais</b>. O tributo pago nas compras de S ficou 'preso' na cadeia. Para o cliente ficar indiferente, S teria de cobrar cerca de <b>R$ 80.757</b> (80.757 x 0,99064 = 80.001) e sua margem cairia para cerca de <b>R$ 12.662</b>.</p></div>"}, {"h": "E se S optar pelo regime regular?", "b": "<div class=\"box\"><span class=\"bl\">Cenário híbrido</span><p>S cobra o mesmo preço sem tributo de R (80.000; nota 101.200). DAS sem a parcela IBS/CBS: 5,064% x 80.000 = <b>4.051,20</b> (hipótese: 6% - 0,936%). IBS/CBS: 21.200 - 13.250 = 7.950. Margem: 101.200 - 63.250 - 7.950 - 4.051,20 = <b>25.948,80</b>. Cliente: crédito de 21.200, custo líquido <b>80.000</b>.</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Cenário de S</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Nota</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Custo líquido do cliente</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Margem de S</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Tradicional, preço 100.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>100.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>99.064</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>30.750</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Tradicional, ajustado para igualar R</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>≈ 80.757</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>≈ 80.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>≈ 12.662</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Híbrido, mesmo preço de R</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>101.200</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>80.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>25.949</td></tr></table></div><div class=\"box tip\"><span class=\"bl\">Regra prática</span><p>Mais vantajoso o <b>híbrido</b> quando S: (1) vende a <b>contribuintes do regime regular</b> que aproveitam crédito; (2) tem <b>muitos insumos tributados</b>; (3) o cliente exige crédito integral. O <b>tradicional</b> tende a servir a quem vende ao <b>consumidor final</b> ou a quem tem poucos insumos. Decisão final: simular com as alíquotas do ano e com a faixa do Anexo; a opção é semestral e irretratável.</p></div><div class=\"box\"><span class=\"bl\">Crédito de quem compra de ME/EPP</span><p>Direito de crédito de IBS e CBS do adquirente <b>não optante</b>, em montante equivalente ao cobrado no regime único, com alíquota informada na nota (LC 123, art. 23, §§ 1º-A e 2º). No mês de início de atividade, vale a <b>menor alíquota</b> dos Anexos (§ 3º). Compras de órgãos públicos de Simples/MEI ficam fora do redutor do art. 472 da LC 214 (parágrafo único, III).</p></div>"}], "V5": [{"h": "O que o texto confirma sobre o MEI", "b": "<div class=\"box\"><span class=\"bl\">Opção e enquadramento</span><p>A opção pelo <b>SIMEI</b> não mudou: faz-se em <b>janeiro</b>, no caso de 2027 até <b>29/01/2027</b> (último dia útil). <b>Todo MEI é optante do Simples</b>: se o Simples exclui, o MEI é <b>desenquadrado automaticamente</b>. Para voltar, <b>não basta regularizar as pendências</b>: é preciso cumprir os requisitos de ingresso no Simples. Pedir só o SIMEI em janeiro cria, se for o caso, a opção pelo Simples.</p></div><div class=\"box\"><span class=\"bl\">IBS recolhido pelo MEI (LC 123, art. 22, V e VI, redação da LC 227/2026)</span><p><b>50%</b> vai ao <b>Município</b> (ou DF) do estabelecimento e <b>50%</b> ao <b>Estado</b> (ou DF). Nas aquisições feitas por MEI, o MEI é tratado como <b>consumo final</b> para a alocação da receita do IBS (LC 227/2026, art. 106, § 5º).</p></div><div class=\"box trap\"><span class=\"bl\">Sem confirmação nas fontes</span><p><b>Limite anual de receita do MEI, valor do DAS-MEI e se a compra do MEI gera crédito ao adquirente:</b> o texto estudado trata do crédito do § 1º-A para ME/EPP optante. <b>Confira</b> a LC 123 e o regulamento vigentes (o limite tradicional é de R$ 81.000 por ano, mas verifique se houve atualização).</p></div>"}, {"h": "Caso: quanto crédito o cliente tem?", "b": "<div class=\"box\"><span class=\"bl\">Hipótese</span><p>Prestador vende serviço de <b>R$ 8.000</b> a empresa do lucro real. Compare (alíquotas hipotéticas; 26,5% de plena vigência; DAS efetivo de 6% com 15,6% de IBS/CBS).</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Fornecedor</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Documento</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Crédito do cliente</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Regime regular</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>8.000 + 26,5% (2.120)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>R$ 2.120</b></td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>ME/EPP do Simples tradicional</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>8.000 por dentro</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>8.000 x 0,936% = <b>R$ 74,88</b></td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>MEI</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>8.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>No máximo o equivalente ao cobrado no DAS-MEI; <b>confira se há crédito</b> e como se calcula</td></tr></table></div><div class=\"box tip\"><span class=\"bl\">Dica de consultoria</span><p>Para quem compra serviços e mercadorias de MEI, o crédito tende a ser <b>mínimo ou inexistente</b>. Se o cliente é grande e usa crédito, o prestador MEI pode perder competitividade; se o MEI cresce, avalie ME/EPP (limite de ME: R$ 360.000; EPP: até R$ 4.800.000, Perguntão PJ 2026).</p></div>"}], "V6": [{"h": "Quadro comparativo (hipotético)", "b": "<div class=\"box\"><span class=\"bl\">Hipótese</span><p>Comércio. Trimestre: vendas de <b>R$ 300.000</b> e compras de <b>R$ 150.000</b> (valores sem tributo), despesas operacionais de <b>R$ 60.000</b>, lucro de R$ 90.000. IBS/CBS de 26,5% (<b>hipotético</b>); DAS efetivo de 6% com 15,6% de IBS/CBS (<b>hipotético</b>). Não inclui folha, CPP, ISS/ICMS e outros tributos fora do DAS: use só para a mecânica.</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Regime</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IRPJ/CSLL (ou DAS)</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IBS/CBS líquido nas vendas</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IBS/CBS não recuperado nas compras</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Crédito entregue ao cliente</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Lucro real</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>24.600</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>39.750</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>0</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>79.500</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Lucro presumido (8% / 12%)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>6.840</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>39.750</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>0</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>79.500</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Simples tradicional</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>DAS 18.000 (já com IBS/CBS, CPP e ISS/ICMS)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>incluído no DAS</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>39.750</b> (sem crédito)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>2.808</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Simples com regime regular</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>DAS sem IBS/CBS: 15.192</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>39.750</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>0</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>79.500</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>MEI</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Não se aplica: receita acima do limite (confira o valor)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>—</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>—</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>—</td></tr></table></div><div class=\"box tip\"><span class=\"bl\">Como chegar nos números</span><p>IBS/CBS: débito 26,5% x 300.000 = 79.500; crédito 26,5% x 150.000 = 39.750; líquido <b>39.750</b>. Real: IRPJ 15% x 90.000 = 13.500 + adicional 10% x (90.000 - 60.000) = 3.000; CSLL 9% x 90.000 = 8.100; total <b>24.600</b>. Presumido: IRPJ 8% x 300.000 = 24.000 x 15% = 3.600 (sem adicional); CSLL 12% x 300.000 = 36.000 x 9% = 3.240; total <b>6.840</b>. Simples: DAS 6% x 300.000 = 18.000; crédito do cliente 0,936% x 300.000 = 2.808; DAS sem IBS/CBS: 5,064% x 300.000 = 15.192.</p></div><div class=\"box trap\"><span class=\"bl\">Leitura</span><p>O <b>presumido</b> paga menos de renda quando a margem real é alta; o <b>real</b> premia margem baixa; o <b>Simples</b> entrega pouco crédito e não se credita (tradicional). A decisão envolve ainda <b>o perfil do cliente</b>, a folha e o ISS/ICMS, e a opção semestral.</p></div>"}, {"h": "Reflexos contábeis (exemplos mensais, regime regular)", "b": "<div class=\"box\"><span class=\"bl\">Hipótese</span><p>Compra de R$ 50.000 + IBS/CBS de R$ 13.250 (26,5%); venda de R$ 100.000 + IBS/CBS de R$ 26.500. Contas e CPC citados como referência didática: <b>confira</b> a prática e os pronunciamentos vigentes.</p></div><div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Evento</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Lançamento</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Observação</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Compra tributada</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>D Estoque 50.000; D IBS/CBS a recuperar 13.250; C Fornecedores 63.250</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Tributo recuperável <b>não</b> compõe o custo (CPC 16, confira)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Venda tributada</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>D Clientes 126.500; C Receita de vendas 100.000; C IBS/CBS a recolher 26.500</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Tributo por fora: tratar como valor devido a terceiros (CPC 47, confira)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Baixa do estoque</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>D CMV 50.000; C Estoque 50.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Custo sem o tributo recuperável</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Apuração do mês</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>D IBS/CBS a recolher 26.500; C IBS/CBS a recuperar 13.250; C IBS/CBS a pagar 13.250</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Saldo a pagar de R$ 13.250</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Simples tradicional</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Compra: D Estoque 63.250. Venda: C Receita 100.000. DAS: D Deduções da receita 6.000; C DAS a recolher 6.000</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>O tributo da compra é custo; o DAS é deduzido da receita (confira)</td></tr></table></div><div class=\"box trap\"><span class=\"bl\">Pegadinhas contábeis</span><p>(1) Perda de estoque obriga a <b>estornar</b> o crédito (unidade de perdas, módulo 56). (2) Saldo credor não é receita: é ativo a realizar. (3) Mudança de regime no meio do ano exige <b>virada de saldos</b> de tributos a recuperar e a recolher.</p></div>"}, {"h": "Obrigações acessórias e checklist por porte", "b": "<div style='overflow-x:auto'><table style='border-collapse:collapse;width:100%;font-size:.88em'><tr><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Regime</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Obrigações (o que o texto confirma)</th><th style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>IBS/CBS</th></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Lucro real e presumido</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'><b>ECF</b> obrigatória; Lalur físico dispensado (ECF substitui); DCTFWeb; presumido mantém escrituração, Livro Caixa e Registro de Inventário</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Documentos fiscais com IBS/CBS e apuração mensal, pelos portais do Comitê Gestor e da RFB: <b>confira</b> leiaute e prazos</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Simples (ME/EPP)</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>PGDAS-D mensal e DASN; <b>desobrigado da ECF</b>. Se excluído no ano: DASN do período no Simples e ECF do restante</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>No DAS, ou por fora se optou pelo regime regular (Portal do Simples e Portal da Tributação sobre o Consumo)</td></tr><tr><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>MEI</td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Declaração e DAS próprios do SIMEI: <b>confira</b></td><td style='border:1px solid #9994;padding:3px 6px;text-align:left;vertical-align:top'>Dentro do DAS-MEI</td></tr></table></div><div class=\"box\"><span class=\"bl\">Checklist: MEI e microempresa</span><p>1) Confirmar limite de receita e risco de desenquadramento. 2) Avaliar se clientes do lucro real pedem crédito. 3) Para ME: simular tradicional x híbrido antes de setembro/março. 4) Emitir nota com alíquota correta para o crédito do adquirente.</p></div><div class=\"box\"><span class=\"bl\">Checklist: EPP e médio porte</span><p>1) Conferir limite (EPP até R$ 4,8 mi; presumido até R$ 78 mi) e atividade obrigada ao real. 2) Comparar real x presumido com IBS/CBS e margem. 3) Mapear fornecedores do Simples (crédito menor) e do regular. 4) Revisar precificação com IBS/CBS por fora. 5) Calendário de opções.</p></div><div class=\"box tip\"><span class=\"bl\">Checklist: grande porte (lucro real)</span><p>1) Controle de créditos, estornos, saldo credor e ressarcimento. 2) Conciliação contábil de tributos a recuperar. 3) Revisão de contratos e preço com fornecedor do Simples. 4) ECD e ECF e conformidade com os dados de IBS/CBS. 5) Acompanhar regulamento e normas do CGIBS/RFB.</p></div>"}]};
var TEC = [];
var TECNOTA = "Exemplos didáticos com valores e alíquotas hipotéticos. Confira sempre a versão vigente da legislação e do regulamento antes de aplicar a um caso real ou responder prova.";
var UNITS = [{"n": 1, "title": "Panorama: regime de renda x regime de IBS/CBS e a linha do tempo", "cvar": "u1", "lessons": [{"id": "K1", "type": "teoria", "title": "Duas camadas: IRPJ/CSLL e IBS/CBS", "xp": 10, "data": "V1"}, {"id": "K2", "type": "drill", "title": "Praticar · regimes e transição", "xp": 25, "data": ["S1", "S2", "S3", "S4", "T0", "T1", "T2", "T3"]}, {"id": "K3", "type": "flash", "title": "Flashcards · regimes e transição", "xp": 15, "data": [0, 1, 2, 3, 4, 5]}]}, {"n": 2, "title": "Lucro real e presumido: débito menos crédito e reflexos no IRPJ/CSLL", "cvar": "u2", "lessons": [{"id": "K4", "type": "teoria", "title": "Apuração não cumulativa e base do IRPJ/CSLL", "xp": 10, "data": "V2"}, {"id": "K5", "type": "drill", "title": "Praticar · lucro real e presumido", "xp": 25, "data": ["S5", "S6", "S7", "S8", "T4", "T5", "T6", "T7"]}, {"id": "K6", "type": "flash", "title": "Flashcards · lucro real e presumido", "xp": 15, "data": [6, 7, 8, 9, 10, 11, 12]}]}, {"n": 3, "title": "Simples Nacional: DAS, regime regular por opção e prazos", "cvar": "u3", "lessons": [{"id": "K7", "type": "teoria", "title": "Simples tradicional x regime regular (híbrido)", "xp": 10, "data": "V3"}, {"id": "K8", "type": "drill", "title": "Praticar · Simples e regime regular", "xp": 25, "data": ["S9", "S10", "S11", "S12", "S13", "T8", "T9", "T10", "T11"]}, {"id": "K9", "type": "flash", "title": "Flashcards · Simples e regime regular", "xp": 15, "data": [13, 14, 15, 16, 17, 18, 19]}]}, {"n": 4, "title": "Cadeia B2B: o cliente do lucro real e o fornecedor do Simples", "cvar": "u4", "lessons": [{"id": "K10", "type": "teoria", "title": "Impacto do regime do fornecedor no custo do cliente", "xp": 10, "data": "V4"}, {"id": "K11", "type": "drill", "title": "Praticar · cadeia B2B e Simples", "xp": 25, "data": ["S14", "S15", "S16", "S17", "T12", "T13", "T14", "T15"]}, {"id": "K12", "type": "flash", "title": "Flashcards · cadeia B2B e Simples", "xp": 15, "data": [20, 21, 22, 23, 24, 25]}]}, {"n": 5, "title": "MEI: DAS-MEI, repartição do IBS e crédito", "cvar": "u5", "lessons": [{"id": "K13", "type": "teoria", "title": "MEI diante do IBS e da CBS", "xp": 10, "data": "V5"}, {"id": "K14", "type": "drill", "title": "Praticar · MEI", "xp": 25, "data": ["S18", "S19", "S20", "S21", "T16", "T17", "T18", "T19"]}, {"id": "K15", "type": "flash", "title": "Flashcards · MEI", "xp": 15, "data": [26, 27, 28, 29, 30, 31]}]}, {"n": 6, "title": "Planejamento: tabela comparativa, reflexos contábeis, acessórias e checklist", "cvar": "u1", "lessons": [{"id": "K16", "type": "teoria", "title": "Mesmo faturamento, cinco regimes", "xp": 10, "data": "V6"}, {"id": "K17", "type": "drill", "title": "Praticar · planejamento e checklist", "xp": 25, "data": ["S22", "S23", "S24", "S25", "S26", "S27", "T20", "T21", "T22", "T23"]}, {"id": "K18", "type": "flash", "title": "Flashcards · planejamento e checklist", "xp": 15, "data": [32, 33, 34, 35, 36, 37, 38]}]}, {"n": 7, "title": "Fixação", "cvar": "u1", "lessons": [{"id": "Krev", "type": "review", "title": "Revisão geral do módulo", "xp": 60, "data": null}, {"id": "K19", "type": "missao", "title": "Missão TEC Concursos", "xp": 15, "data": null}, {"id": "K20", "type": "prova", "title": "Simulado cronometrado", "xp": 100, "data": null}]}];
var COM = {"0": "<p>Certo. É a literalidade dos §§ 1º e 2º do art. 125 do ADCT.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "1": "<p>Errado. As alíquotas de IBS/CBS não se aplicam às operações dos optantes do Simples em 2026.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "2": "<p>Errado. Lucro presumido é regime de IRPJ/CSLL. Quem não opta fica no regime regular de IBS/CBS.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "3": "<p>Certo. O presumido só altera a base do IRPJ/CSLL; o regime de IBS/CBS é outro.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "4": "<p>Certo. Ambos são contribuintes do regime regular; o regime de IRPJ não muda a técnica.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "5": "<p>Errado. PIS/Pasep e Cofins são extintos a partir de 2027 (ADCT, art. 126, II). O presumido passa a ter crédito de IBS/CBS.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "6": "<p>Errado. A base é um percentual da receita bruta, independentemente de custos, créditos ou perdas.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "7": "<p>Certo. É a alínea 'a' da Pergunta 006 do Cap. XIII do Perguntão PJ 2026.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "8": "<p>Errado. Somente em setembro e março (LC 123, art. 13, § 10; Manual do CGSN).</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "9": "<p>Certo. A ausência de renúncia implica manutenção do regime regular (Roteiro do CGSN, item 4.2).</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "10": "<p>Certo. Vedação descrita no Perguntão PJ 2026 sobre a LC 124/2025.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "11": "<p>Errado. O crédito equivale apenas ao IBS/CBS cobrado no regime único (LC 123, art. 23, § 1º-A).</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "12": "<p>Certo. É a redação do § 1º-A, em linha com a EC 132 (art. 146, § 3º, II).</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "13": "<p>Errado. O crédito é limitado ao que o regime único cobra, normalmente bem menor.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "14": "<p>Certo. Art. 23, § 2º, da LC 123.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "15": "<p>Errado. O custo relevante é o líquido do crédito: nota menos crédito apropriável.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "16": "<p>Certo. Roteiro do CGSN, apresentação do documento.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "17": "<p>Errado. É necessário atender também aos requisitos para ingresso no Simples.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "18": "<p>Certo. LC 123, art. 22, V e VI (redação da LC 227/2026).</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "19": "<p>Errado. Não houve alteração: a opção pelo SIMEI é em janeiro (até 29/01/2027).</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "20": "<p>Errado. Depende da margem, dos insumos, do perfil do cliente e do crédito; só a simulação responde.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "21": "<p>Certo. Perguntão PJ 2026, ECF, Pergunta 002, item I.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "22": "<p>Certo. Atenção da Pergunta 002 do Perguntão PJ 2026.</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>", "23": "<p>Errado. Em regra são ativo a recuperar e não compõem o custo (CPC 16: confira).</p><p class='fb-fonte'>Casos práticos (exemplos didáticos) com base na EC 132/2023, LC 214/2025 e LC 227/2026</p>"};
var PROVA_POOL=[];
for(var k in EX){ if(EX[k].t!=="match") PROVA_POOL.push(k); }
return {n:"60", nome:"Casos práticos 10: lucro real, presumido, Simples Nacional e MEI diante da reforma", pronto:true,
 CARDS:CARDS, QS:QS, FEY:{}, TEORIA:TEORIA, EX:EX, KIT:{}, UNITS:UNITS, COM:COM,
 DISCURSIVA:"", CASO:"", TEC:TEC, TECNOTA:TECNOTA, PROVA_POOL:PROVA_POOL};
})();
